pub mod tuning {
    /// seen in game: 0.0075 made him 1.5x the Tarnished; 0.0055 puts his ~370-unit pose at about 2 m, a head taller (m per League unit)
    pub const MODEL_SCALE: f32 = 0.0055;
    /// League ranges feel short against Elden Ring enemies; AA 480 -> 5.8 m, E 850 -> 10.2 m (m per League unit)
    pub const RANGE_SCALE: f32 = 0.012;
    /// levelling at graces still matters: level 50 -> 196 AP, level 150 -> 596 AP (ability power per Elden Ring level above 1)
    pub const AP_PER_RUNE_LEVEL: f32 = 4.0;
    /// League damage against Elden Ring HP is already close (Limgrave soldier ~150 HP vs Q 40-120) (x)
    pub const DAMAGE_SCALE: f32 = 1.0;
    /// a Limgrave soldier (~200 HP) gives 70 XP, like a League minion wave share (xp per max HP of a killed enemy)
    pub const XP_PER_ENEMY_HP: f32 = 0.35;
    /// weak critters still count (xp)
    pub const XP_MIN: f32 = 20.0;
    /// a boss is worth about a level (xp)
    pub const XP_MAX: f32 = 1500.0;
    /// without lock-on, basic attacks and Terror pick the nearest enemy in front of the camera (degrees)
    pub const AA_CONE_DEG: f32 = 75.0;
    /// crow bolts visibly travel (m/s)
    pub const MISSILE_SPEED: f32 = 18.0;
    /// League silences enemies in the centre of Reap (fraction of E radius)
    pub const E_SILENCE_INNER: f32 = 0.4;
    /// League Crowstorm ticks 4 times per second (ticks)
    pub const R_TICKS_PER_SECOND: f32 = 4.0;
    /// turns League's model forward onto the Tarnished's facing; checked in game (degrees)
    pub const MODEL_YAW_DEG: f32 = 0.0;
    /// League meshes are authored mirrored in X relative to some engines; checked in game (+1 or -1)
    pub const MODEL_MIRROR_X: f32 = 1.0;
    /// League's Reap slow lasts 1.25 s (tooltip); the spell data only has the silence duration (s)
    pub const E_SLOW_DURATION: f32 = 1.25;
    /// Terrify stuns (creator: no fleeing): the enemy freezes in place, no actions or movement, until it ends (x animation speed)
    pub const FEAR_ANIM_SPEED: f32 = 0.0;
    /// League's lines are mastered far louder than Elden Ring's mix: 0.8 was much too loud in game; 0.3 -> 0.22 (creator: a bit lower) (x League's mix)
    pub const AUDIO_VOLUME: f32 = 0.22;
    /// Attack1 is 0.33 s raw (too snappy) and 0.75 of the 1.6 s period (1.2 s) felt sluggish: ~0.55 s at level 1, back to the raw clip at high attack speed (of the attack period)
    pub const AA_ANIM_FRACTION: f32 = 0.35;
    /// the bolt leaves his demon hand a little before the middle of the swing (FiddleSticks_BA_Cas runs frames 8-19 of 37) (of the attack animation)
    pub const AA_WINDUP_FRACTION: f32 = 0.4;
    /// League plays Melee_Attack1/2 when the target is right next to him: a claw swipe, no bolt (m)
    pub const MELEE_RANGE: f32 = 2.5;
    /// the Tarnished's movement slows down hard while Bountiful Harvest drains, back to normal when it ends (creator's request) (x Tarnished animation speed)
    pub const W_SELF_SLOW: f32 = 0.3;
    /// Reap's League damage (with the AP the rune level gives) one-shot the early guards; the creator found it too strong (x)
    pub const E_DAMAGE_MULT: f32 = 0.5;
    /// Terrify's icon floats over a feared head (m)
    pub const FEAR_ICON_SIZE: f32 = 0.55;
    /// after the channel Crowstorm launches him forward (or at the locked target) like a jump (creator's request) (s)
    pub const R_LEAP_TIME: f32 = 0.45;
    /// how far the Crowstorm jump carries him with no locked target (m)
    pub const R_LEAP_DISTANCE: f32 = 7.0;
    /// the arc of the jump (drawn on Fiddlesticks' model; the Tarnished's own position follows the ground) (m)
    pub const R_LEAP_HEIGHT: f32 = 1.6;
    /// Fiddlesticks shrugs off staggers (creator's request): the Tarnished's poise is refilled to this every frame (poise)
    pub const CC_IMMUNE_POISE: f32 = 100000.0;
    /// the poise he would really have (his Elden Ring maximum) refills after this long without being hit, like the game's own; when hits would have broken it while he drains, Bountiful Harvest is interrupted (s)
    pub const CC_POISE_RESET: f32 = 3.0;
    /// League particle blendMode 0 -> none/opaque; League does not document them, read off which textures use each (renderer blend: 0 alpha, 1 add, 2 premultiplied, 3 screen, 4 multiply)
    pub const VFX_BLEND_0: f32 = 0.0;
    /// League particle blendMode 1 -> alpha blend (dark smoke, crows, shadowy beams); League does not document them, read off which textures use each (renderer blend: 0 alpha, 1 add, 2 premultiplied, 3 screen, 4 multiply)
    pub const VFX_BLEND_1: f32 = 0.0;
    /// League particle blendMode 2 -> additive (bright sparks, flares); League does not document them, read off which textures use each (renderer blend: 0 alpha, 1 add, 2 premultiplied, 3 screen, 4 multiply)
    pub const VFX_BLEND_2: f32 = 1.0;
    /// League particle blendMode 3 -> unused by Fiddlesticks; additive; League does not document them, read off which textures use each (renderer blend: 0 alpha, 1 add, 2 premultiplied, 3 screen, 4 multiply)
    pub const VFX_BLEND_3: f32 = 1.0;
    /// League particle blendMode 4 -> additive: as premultiplied it drew opaque black squares (textures whose black is meant to vanish) (renderer blend: 0 alpha, 1 add, 2 premultiplied, 3 screen, 4 multiply)
    pub const VFX_BLEND_4: f32 = 1.0;
    /// League particle blendMode 5 -> screen (soft glows, rays, embers); League does not document them, read off which textures use each (renderer blend: 0 alpha, 1 add, 2 premultiplied, 3 screen, 4 multiply)
    pub const VFX_BLEND_5: f32 = 3.0;
    /// League effects that fly from a drained enemy to Fiddlesticks (W heal) take this long (s)
    pub const VFX_FLY_TIME: f32 = 0.45;
    /// how fast Fiddlesticks' model turns to a new direction (higher = snappier; ~12 turns most of the way in 0.2 s) instead of snapping (1/s)
    pub const MODEL_TURN_RATE: f32 = 12.0;
    /// Elden Ring's HUD is hidden (CSFeManImp.hud_state HideAll, set after MenuMan each frame; zeroing its values did nothing) and the mod draws enemy health bars and a boss bar itself. HideAll also hides the compass and rune count (1 = on)
    pub const HIDE_ER_BARS: f32 = 1.0;
    /// after a boss dies, the item choice opens once every boss health bar has been gone this long (a boss's second phase keeps its bar) (s)
    pub const ITEM_OFFER_DELAY: f32 = 2.0;
    /// a strong (team 7) enemy dying this close to a full-screen banner request (ENEMY FELLED) counts as a boss: the boss health bars are not filled while Elden Ring's HUD is hidden (s)
    pub const BOSS_BANNER_WINDOW: f32 = 6.0;
}
